<?php namespace App\Features\Stock\Livewire;use Livewire\Component;use Livewire\WithFileUploads;use App\Features\Stock\Models\Stock;use App\Features\Stock\Services\StockService;
class StockDetail extends Component{use WithFileUploads;public Stock $stock;public $cover;public function mount(Stock $stock){$this->authorize('view',$stock);$this->stock=$stock;}public function save(StockService $service){$this->authorize('update',$this->stock);$data=$this->validate(['stock.name'=>'required|string|max:150','stock.sku'=>'nullable|string|max:60','stock.description'=>'nullable|string','stock.quantity'=>'required|integer|min:0','stock.unit'=>'required|string|max:20','stock.price'=>'nullable|numeric|min:0','stock.min_stock'=>'required|integer|min:0','cover'=>'nullable|image|max:2048']);if($this->cover)$this->stock->cover_image_path=$this->cover->store('stocks','public');$service->update($this->stock,$data['stock']);session()->flash('success','Stok diperbarui.');}public function adjust(int $amount,StockService $service){$this->authorize('update',$this->stock);$service->adjust($this->stock,$amount);}public function render(){return view('livewire.stock.stock-detail')->layout('components.layouts.app');}}
